import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

// Min reduction over dim=1 of a [B, D1, D2] contiguous float tensor.
// Vectorized-load version: each warp reduces 128 consecutive columns of
// one batch row. Every lane owns 4 consecutive outputs and reads them
// with one aligned 16-byte float4 load per row, plus a second aligned
// float4 (almost always an L1 hit) used to realign the row data when
// the row start is not 16-byte aligned (dim2 not a multiple of 4).
// This cuts global load instructions in half versus scalar 4-byte
// loads while keeping every transaction coalesced and aligned. Rows
// whose realigned window could cross the end of the allocation (only
// possible in the very last batch/row) fall back to guarded scalar loads.
__global__ void min_reduce_dim1_kernel(const float* __restrict__ x,
                                       float* __restrict__ out,
                                       int dim1, int dim2,
                                       long long total) {
    const int lane = threadIdx.x & 31;
    const long long numWarps = ((long long)gridDim.x * blockDim.x) >> 5;
    const long long batch = total / dim2;
    const int chunksPerBatch = (dim2 + 127) >> 7;
    const long long numChunks = batch * (long long)chunksPerBatch;
    const long long totalFloats = total * (long long)dim1;
    const float inf = __int_as_float(0x7f800000);
    for (long long w = ((long long)blockIdx.x * blockDim.x + threadIdx.x) >> 5;
         w < numChunks; w += numWarps) {
        const long long b = w / chunksPerBatch;
        const int d0 = (int)(w - b * (long long)chunksPerBatch) << 7;
        const long long rowBase = b * (long long)dim1 * dim2;
        int valid = dim2 - d0;
        if (valid > 128) valid = 128;
        float4 m = make_float4(inf, inf, inf, inf);
        const float* s = x + rowBase + d0;
        const bool allSafe =
            (rowBase + (long long)(dim1 - 1) * dim2 + d0 + 132) <= totalFloats;
        if (allSafe) {
            for (int i = 0; i < dim1; ++i, s += dim2) {
                const int off = (int)(((size_t)s) >> 2) & 3;
                const float4* a4 = (const float4*)(s - off);
                const float4 cur = __ldg(a4 + lane);
                const float4 nxt = __ldg(a4 + lane + 1);
                float4 r;
                switch (off) {
                    case 0:  r = cur; break;
                    case 1:  r = make_float4(cur.y, cur.z, cur.w, nxt.x); break;
                    case 2:  r = make_float4(cur.z, cur.w, nxt.x, nxt.y); break;
                    default: r = make_float4(cur.w, nxt.x, nxt.y, nxt.z); break;
                }
                m.x = fminf(m.x, r.x);
                m.y = fminf(m.y, r.y);
                m.z = fminf(m.z, r.z);
                m.w = fminf(m.w, r.w);
            }
        } else {
            for (int i = 0; i < dim1; ++i, s += dim2) {
                if (rowBase + (long long)i * dim2 + d0 + 132 <= totalFloats) {
                    const int off = (int)(((size_t)s) >> 2) & 3;
                    const float4* a4 = (const float4*)(s - off);
                    const float4 cur = __ldg(a4 + lane);
                    const float4 nxt = __ldg(a4 + lane + 1);
                    float4 r;
                    switch (off) {
                        case 0:  r = cur; break;
                        case 1:  r = make_float4(cur.y, cur.z, cur.w, nxt.x); break;
                        case 2:  r = make_float4(cur.z, cur.w, nxt.x, nxt.y); break;
                        default: r = make_float4(cur.w, nxt.x, nxt.y, nxt.z); break;
                    }
                    m.x = fminf(m.x, r.x);
                    m.y = fminf(m.y, r.y);
                    m.z = fminf(m.z, r.z);
                    m.w = fminf(m.w, r.w);
                } else {
                    #pragma unroll
                    for (int j = 0; j < 4; ++j) {
                        const int dd = 4 * lane + j;
                        if (dd < valid) {
                            const float v = __ldg(s + dd);
                            if (j == 0)      m.x = fminf(m.x, v);
                            else if (j == 1) m.y = fminf(m.y, v);
                            else if (j == 2) m.z = fminf(m.z, v);
                            else             m.w = fminf(m.w, v);
                        }
                    }
                }
            }
        }
        float* ob = out + b * (long long)dim2 + d0;
        #pragma unroll
        for (int j = 0; j < 4; ++j) {
            const int dd = 4 * lane + j;
            if (dd < valid) {
                ob[dd] = (j == 0) ? m.x : (j == 1) ? m.y : (j == 2) ? m.z : m.w;
            }
        }
    }
}

torch::Tensor min_reduce_dim1(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "input must be 3D");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "input must be float32");

    auto xc = x.contiguous();
    int64_t batch = xc.size(0);
    int64_t dim1  = xc.size(1);
    int64_t dim2  = xc.size(2);

    auto out = torch::empty({batch, dim2}, xc.options());
    long long total = (long long)batch * dim2;
    if (total == 0) return out;

    int threads = 256;
    long long chunksPerBatch = (dim2 + 127) / 128;
    long long blocks = (batch * chunksPerBatch * 32 + threads - 1) / threads;
    if (blocks > 65535) blocks = 65535;

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    min_reduce_dim1_kernel<<<(int)blocks, threads, 0, stream>>>(
        xc.data_ptr<float>(), out.data_ptr<float>(),
        (int)dim1, (int)dim2, total);
    return out;
}
"""

_cpp_src = "torch::Tensor min_reduce_dim1(torch::Tensor x);"

_mod = load_inline(
    name="min_reduce_dim1_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["min_reduce_dim1"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs min reduction over a specific dimension,
    using a custom CUDA kernel for the dim == 1 case.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if (self.dim == 1 and x.is_cuda and x.dim() == 3
                and x.dtype == torch.float32):
            return _mod.min_reduce_dim1(x)
        return torch.min(x, dim=self.dim)[0]

