// Consecutive threads map to consecutive d, so all global loads are
// perfectly coalesced even though the reduction stride is D2.
__global__ void min_reduce_dim1_kernel(const float* __restrict__ x,
                                       float* __restrict__ out,
                                       int dim1, int dim2,
                                       long long total) {
    // Warp-coarsened reduction: each warp handles 128 consecutive output
    // elements (4 per lane, strided by 32 so every load instruction is
    // still fully coalesced across the warp). Each lane keeps 4
    // independent accumulator chains and the dim1 loop is unrolled by 2,
    // giving up to 8 outstanding global loads per thread to hide memory
    // latency and saturate bandwidth on this memory-bound reduction.
    const int lane = threadIdx.x & 31;
    const long long numWarps = ((long long)gridDim.x * blockDim.x) >> 5;
    const long long numChunks = (total + 127) >> 7;
    const float inf = __int_as_float(0x7f800000);
    for (long long w = ((long long)blockIdx.x * blockDim.x + threadIdx.x) >> 5;
         w < numChunks; w += numWarps) {
        long long o0 = (w << 7) + lane;
        const float* p[4];
        long long o[4];
        float m[4];
        #pragma unroll
        for (int k = 0; k < 4; ++k) {
            o[k] = o0 + 32 * k;
            long long oo = (o[k] < total) ? o[k] : 0;
            int b = (int)(oo / dim2);
            int d = (int)(oo - (long long)b * dim2);
            p[k] = x + (long long)b * dim1 * dim2 + d;
            m[k] = inf;
        }
        int i = 0;
        for (; i + 1 < dim1; i += 2) {
            #pragma unroll
            for (int k = 0; k < 4; ++k) {
                float v0 = __ldcs(p[k]);
                float v1 = __ldcs(p[k] + dim2);
                m[k] = fminf(m[k], fminf(v0, v1));
                p[k] += 2 * (long long)dim2;
