        }
        if (i < dim1) {
            #pragma unroll
            for (int k = 0; k < 4; ++k) {
                m[k] = fminf(m[k], __ldcs(p[k]));
            }
        }
        #pragma unroll
        for (int k = 0; k < 4; ++k) {
            if (o[k] < total) out[o[k]] = m[k];
